export async function getCustomerOrderHistory(userId: string) {
  // Query independent service APIs concurrently rather than joining tables directly
  const [user, orders] = await Promise.all([
    userService.fetchUser(userId),
    orderService.fetchOrdersForUser(userId),
  ]);

  // Stitch relational payload in application memory
  return {
    customer: { id: user.id, name: user.name, tier: user.tier },
    orders: orders.map(o => ({ orderId: o.id, total: o.total, status: o.status })),
  };
}
